// Configuration de la caméra et du Raymarching
#define NOMBRE_PASCAL_MAX 100.0
#define POSITION_CAMERA vec3(0.0, 0.45, -3.0)
#define ECHELLE_CHAMP_VISION 1.6

// Constantes de rotation
#define VECTEUR_ROTATION vec4(0.0, 1.57, -1.57, 0.0)
#define ANGLE_ROTATION_FRACTALE 24.8

// Initialisation de la scène
#define DISTANCE_RAYON_INITIALE 9.7
#define ECHELLE_INITIALE 2.6
#define DISTANCE_FORME_INITIALE 29.6
#define ITERATIONS_FRACTALE 9

// Transformation de la fractale
#define DECALAGE_PLIAGE 0.5
#define REGULARISATION 0.07
#define HAUTEUR_PLIAGE 1.71

// Rendu volumétrique et couleurs
#define DECALAGE_EXP_LUMIERE 5.5
#define SEUIL_HAUTEUR 1.0
#define COULEUR_DE_BASE vec3(2.8)
#define COULEUR_HAUTEUR vec3(-0.4)
#define COULEUR_ACCENTUATION vec3(0.0, 0.15, 0.0)

// Transitions de couleur
#define DECALAGE_TRANSITION_COULEUR 0.43
#define ECHELLE_TRANSITION_COULEUR 0.3
#define ECHELLE_ATTENUATION_HAUTEUR 0.31

#define VALEUR_ALPHA 1.0

void mainImage(out vec4 couleurSortie, in vec2 coordonneesFragment)
{
    vec3 positionCamera = POSITION_CAMERA;
    vec3 positionRayon;
    vec3 couleurAccumulee = positionCamera - positionCamera;
    float distancePas = 0.;
    float facteurEchelle;
    float distanceForme;
    float facteurEchelleAccumule;
    float compteurIteration = 0.;
    float distanceAccumulee;

    for(; compteurIteration++ < NOMBRE_PASCAL_MAX;)
    {
        positionRayon = positionCamera += vec3((coordonneesFragment.xy 
            - .5 * iResolution.xy) / iResolution.y, ECHELLE_CHAMP_VISION) * distancePas;
        positionRayon.xz *= mat2(cos(iTime + VECTEUR_ROTATION));
        distancePas = DISTANCE_RAYON_INITIALE;
        facteurEchelleAccumule = ECHELLE_INITIALE;
        distanceForme = DISTANCE_FORME_INITIALE;

        for(int indice = 0; indice < int(ITERATIONS_FRACTALE); indice++)
        {
            positionRayon.xz = abs(positionRayon.xz * mat2(cos(ANGLE_ROTATION_FRACTALE + VECTEUR_ROTATION))) - DECALAGE_PLIAGE;
            distanceAccumulee = dot(positionRayon, positionRayon);
            facteurEchelleAccumule /= distanceAccumulee;
            positionRayon /= distanceAccumulee + REGULARISATION;
            positionRayon.y = HAUTEUR_PLIAGE - positionRayon.y;
            distanceForme = min(distanceForme, length(positionRayon.xz));
            distancePas = min(distancePas, max(length(positionRayon.xz), positionRayon.y) 
                / facteurEchelleAccumule);
        }

        facteurEchelle = step(SEUIL_HAUTEUR, positionCamera.y);
        couleurAccumulee += exp(-positionRayon.y / facteurEchelleAccumule - DECALAGE_EXP_LUMIERE) * mix(mix(COULEUR_DE_BASE, 
            COULEUR_HAUTEUR, facteurEchelle), COULEUR_ACCENTUATION, clamp((DECALAGE_TRANSITION_COULEUR - distanceForme) 
            / ECHELLE_TRANSITION_COULEUR, 0., 1.) * clamp(positionCamera.y / ECHELLE_ATTENUATION_HAUTEUR, 0., 1.) * (1. - facteurEchelle));
        distancePas = min(distancePas, positionCamera.y);
    }

    couleurSortie = vec4(couleurAccumulee, VALEUR_ALPHA);
}
